package com.nequard.bandwidth;
import com.nequard.auth.OrganizationAccessService;import com.nequard.community.CommunityNode;import com.nequard.community.CommunityNodeRepository;import org.springframework.security.core.Authentication;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/v1/bandwidth") public class BandwidthController{
private final BandwidthRepository repo;private final CommunityNodeRepository nodes;private final OrganizationAccessService access;
public BandwidthController(BandwidthRepository r,CommunityNodeRepository n,OrganizationAccessService a){repo=r;nodes=n;access=a;}
@GetMapping("/allocations")public List<BandwidthAllocation> all(Authentication a){return access.isSuperAdmin(a)?repo.findAll():repo.findByOrganizationId(access.currentOrganization(a));}
@GetMapping("/nodes/{nodeId}")public List<BandwidthAllocation> node(Authentication a,@PathVariable UUID nodeId){CommunityNode n=nodes.findById(nodeId).orElseThrow(()->new NoSuchElementException("COMMUNITY_NODE_NOT_FOUND"));if(!access.canAccess(a,n.getOrganizationId()))throw new SecurityException("TENANT_ACCESS_DENIED");return repo.findByNodeId(nodeId);}
@PostMapping("/allocations")@PreAuthorize("hasAnyRole('SUPER_ADMIN','NETWORK_ADMIN','COMMUNITY_ADMIN','INTERNET_PROVIDER')")public BandwidthAllocation create(Authentication a,@RequestBody BandwidthAllocation x){CommunityNode n=nodes.findById(x.getNodeId()).orElseThrow(()->new NoSuchElementException("COMMUNITY_NODE_NOT_FOUND"));x.setOrganizationId(access.requireOrganization(a,n.getOrganizationId()));return repo.save(x);}}